-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "Elementale"
L["rm.era.shaman.elemental.Description"] = "Elementale dal livello 10 (la maggior parte dei punti in Elementale); costruita a partire da Icy Veins e Wowhead. Folgore della Terra interrompe e finisce un bersaglio in punto di morte. In movimento: Folgore del Fuoco, altrimenti Folgore del Gelo. Da solo con il bersaglio in mischia: Folgore della Terra sopra il 30% di salute, poi mischia. Contro tre o più nemici: Totem dell'Esplosione di Fuoco e Totem del Magma quando sei in mischia, e Catena di Fulmini. Catena di Fulmini con Maestria Elementale o Lancio Istintivo, altrimenti Dardo Fulminante. Promemoria: Scudo di Fulmini, Roccia Dura fuori dalle incursioni, Totem delle Fiamme o del Magma, Totem del Flusso di Mana o del Flusso Vitale, Maestria Elementale con Catena di Fulmini pronta, Rapidità della Natura e Ondata di Cura sotto il 30%, cure dopo un ingaggio. Dissoluzioni, epurazioni e uso dei gradi inferiori restano a te."
L["rm.era.shaman.elemental.simulator.Name"] = "Elementale, Catena di Fulmini appena pronta (simulatore)"
L["rm.era.shaman.elemental.simulator.Description"] = "La lista Elementale di simulatore, un'alternativa alla rotazione integrata consigliata Elementale, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Catena di Fulmini appena pronta anche su un solo bersaglio, Folgore della Terra mentre Maestria Elementale è attiva, altrimenti Dardo Fulminante. Più veloce ma molto più avida di mana della rotazione integrata consigliata; stessa interruzione, stessi totem e promemoria."
L["rm.era.shaman.enhancement.Name"] = "Potenziamento"
L["rm.era.shaman.enhancement.Description"] = "Livelli 1–60, anche sui reami Hardcore e Self-Found, e ogni Sciamano senza una maggioranza di talenti; costruita a partire da Icy Veins, Wowhead e simulatore. Dardo Fulminante ingaggia dalla distanza; Folgore della Terra interrompe. In incursione solo Assalto della Tempesta e Folgore del Gelo (posti per le penalità). Contro tre o più nemici che ti combattono, Totem dell'Esplosione di Fuoco e Totem del Magma. Poi Assalto della Tempesta, Folgore della Terra sulla penalità di Assalto della Tempesta o per finire, Folgore del Fuoco quando farà effetto per tutta la durata, Folgore della Terra finché hai metà del tuo mana, e Dardo Fulminante mentre sei fuori portata. Promemoria: Roccia Dura da solo e Arma della Furia del Vento nelle spedizioni, Scudo di Fulmini, Totem della Forza della Terra, delle Fiamme, della Furia del Vento o della Grazia dell'Aria, del Flusso di Mana o del Flusso Vitale, cure dopo un ingaggio e nelle emergenze. Artiglio di Pietra, Vincolo Terrestre, alternanza dei totem e abilità razziali sono elencate ma disattivate; dissoluzioni, epurazioni e totem purificatori restano a te."
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "Potenziamento, prima Folgore del Fuoco (Warcraft Tavern)"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "Il Potenziamento di Warcraft Tavern, un'alternativa alla rotazione integrata consigliata Potenziamento, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Arma della Furia del Vento appena la apprendi, Assalto della Tempesta, Folgore del Fuoco prima di qualsiasi folgore diretta, poi Folgore della Terra finché la tua minaccia è bassa, o Folgore del Gelo in gruppo una volta che è alta; Totem del Magma e Catena di Fulmini sui gruppi di nemici. Stessi totem e promemoria della rotazione integrata consigliata."
L["rm.era.shaman.restoration.Name"] = "Rigenerazione"
L["rm.era.shaman.restoration.Description"] = "Rigenerazione dal livello 10 (la maggior parte dei punti in Rigenerazione); costruita a partire da Icy Veins e Wowhead. Sul tuo bersaglio amico: Ondata di Cura con Rapidità della Natura, Rapidità della Natura sotto il 30%, Ondata di Cura Inferiore sotto il 40%, Cura dei Veleni o Rimuovi Malattia, Catena di Guarigione quando tre membri del gruppo vicini a te sono sotto l'85%, altrimenti Ondata di Cura sotto il 90%. Su un nemico combatte: Folgore della Terra per interrompere, Catena di Fulmini sui gruppi di nemici, Folgore del Fuoco, Dardo Fulminante dalla distanza, mischia. Promemoria: Scudo di Fulmini e Roccia Dura da solo, Totem della Marea di Mana in gruppo, Totem del Flusso di Mana, della Forza della Terra, delle Fiamme. La scelta di chi curare, l'uso dei gradi inferiori e i totem del Tremore o purificatori restano a te; mantenere Via di Guarigione sul difensore è elencato ma disattivato."
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "Rigenerazione, prima Catena di Guarigione (Warcraft Tavern)"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "La Rigenerazione di Warcraft Tavern, un'alternativa alla rotazione integrata consigliata Rigenerazione, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Catena di Guarigione è la cura per chiunque sia sotto il 90%, con Ondata di Cura Inferiore per chi sta per morire; Ondata di Cura è solo per un guaritore assegnato al difensore con Via di Guarigione (elencata ma disattivata). Stesse rimozioni, stessi danni sui nemici e promemoria dei totem della rotazione integrata consigliata."
L["rm.forever.shaman.elemental.Name"] = "Elementale"
L["rm.forever.shaman.elemental.Description"] = "Elementale a distanza una volta che Elementale è il tuo albero dei talenti principale con 21 punti (il livello di Esplosione di Lava), secondo Icy Veins (prima di allora la rotazione integrata Potenziamento gioca l'ibrido in mischia che ogni guida consiglia). Ingaggia con Dardo del Fulmine (Catena di Fulmini su un gruppo), in movimento lancia solo incantesimi istantanei, usa Nova di Fuoco e Catena di Fulmini contro tre o più nemici, mantiene Folgore Fiammeggiante, Esplosione di Lava appena pronta, Assalto della Tempesta e Folgore della Terra se conosci Assalto della Tempesta, Nova di Fuoco con Lucidità in gruppo, poi Dardo del Fulmine. Promemoria: scudo, incantamento dell'arma, Totem delle Fiamme o Totem del Magma, totem di gruppo, Signore degli Elementi, interruzione. Su Forever salute e mana sono nascosti agli addon, quindi curarti e fermarti a ricaricare il mana sono una tua scelta. Restano a te: il kiting con Vincolo Terrestre, Folgore del Gelo, Epurazione e gli altri totem."
L["rm.forever.shaman.enhancement.Name"] = "Potenziamento (Icy Veins)"
L["rm.forever.shaman.enhancement.Description"] = "Potenziamento in mischia dal livello 1 al 60, e la scelta predefinita per qualsiasi Sciamano prima di Esplosione di Lava o Totem della Marea di Mana. Ingaggia con Dardo del Fulmine dalla distanza, poi Assalto della Tempesta appena pronto, un Dardo del Fulmine istantaneo a cinque cumuli di Arma del Maelstrom, Nova di Fuoco (con un totem del Fuoco piazzato) e Folgore Fiammeggiante contro tre o più nemici, Folgore della Terra sulla penalità di Assalto della Tempesta, Folgore Fiammeggiante in gruppo e Folgore della Terra appena pronta; Dardo del Fulmine riempie i vuoti mentre il bersaglio è fuori portata. Su Forever salute e mana sono nascosti agli addon, quindi curarti e fermarti a ricaricare il mana sono una tua scelta (la rotazione integrata di Wowhead risparmia invece il mana). Promemoria: incantamento dell'arma (Furia del Vento, altrimenti Lingua di Fuoco, altrimenti Mordiroccia), Scudo d'Acqua o Scudo di Fulmini, l'interruzione con Folgore della Terra, Totem delle Fiamme o Totem del Magma, totem di gruppo, Ira del Veggente, Totem dell'Artiglio di Pietra. Restano a te: le preimpostazioni dei totem, Folgore del Gelo, Epurazione e gli altri totem."
L["rm.forever.shaman.enhancement.wowhead.Name"] = "Potenziamento, risparmio di mana (Wowhead)"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "Il Potenziamento a risparmio di mana di Wowhead e Mobalytics: l'attacco automatico fa il lavoro, Assalto della Tempesta solo mentre la rigenerazione di mana di Assalto della Tempesta Migliorato non è attiva, nessuna Folgore della Terra nella rotazione (le folgori servono per ingaggiare e interrompere), e in gruppo o contro i gruppi di nemici Totem delle Fiamme con Nova di Fuoco appena pronta. Stessi promemoria per incantamento, scudo e interruzione della rotazione integrata Icy Veins. Sceglila al posto di quella rotazione integrata se resti senza mana. Un'alternativa alla rotazione integrata consigliata Potenziamento, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.forever.shaman.restoration.Name"] = "Rigenerazione"
L["rm.forever.shaman.restoration.Description"] = "Cure, una volta che Rigenerazione è il tuo albero dei talenti principale con 16 punti (il livello del Totem della Marea di Mana), secondo Icy Veins. Con un bersaglio amico: un'Onda di Guarigione istantanea dopo che hai usato Rapidità della Natura, Cura Veleno e Cura Malattia, Riflusso su un bersaglio che non lo ha, Catena di Guarigione in gruppo, Onda di Guarigione. Scegli chi curare prendendolo come bersaglio; su Forever salute e mana sono nascosti agli addon, quindi decidi tu quando usare Rapidità della Natura e Onda di Guarigione Inferiore. Con un bersaglio ostile e nessuno da curare: Nova di Fuoco e Catena di Fulmini contro i gruppi, Assalto della Tempesta e Folgore della Terra se conosci Assalto della Tempesta, Folgore Fiammeggiante su élite e boss, Dardo del Fulmine, poi mischia. Promemoria: Scudo d'Acqua, l'interruzione con Folgore della Terra, Marea di Mana e i totem di potenziamento del gruppo. Restano a te: l'uso dei gradi inferiori, gli altri totem, Epurazione e Lupo Spettrale."
L["rm.mop.shaman.elemental.Name"] = "Consigliata"
L["rm.mop.shaman.elemental.Description"] = "Consigliata per Elementale dal livello 10, scelta nella specializzazione Elementale. L'ordine di Wowhead: un Dardo Fulminante per aprire (Getto di Lava con Furia Scatenata), Scarica degli Elementi con Furia Scatenata, Folgore del Fuoco quando manca o sta per scadere su un bersaglio che sopravvivrà, Getto di Lava sul bersaglio con Folgore del Fuoco (e a ogni Eruzione di Lava), Detonazione Elementale, Folgore della Terra a sei cariche di Scudo di Fulmini mentre a Folgore del Fuoco restano 6 secondi, Catena di Fulmini contro due nemici, Dardo Fulminante. Quattro o più nemici addosso: Totem del Magma in mischia, Getti di Lava gratuiti, Raggio di Lava durante Ascesa, Catena di Fulmini. In movimento mostra solo incantesimi istantanei. Promemoria: Scudo di Fulmini, Lingua di Fuoco, Totem delle Fiamme, Elementale del Fuoco su élite e boss, Maestria Elementale, Ascesa dopo un Getto di Lava, Rapidità Ancestrale, Totem della Sferzata della Tempesta e Brama di Sangue in gruppo, Raffica di Vento, Esplosione Tonante per il mana, Ira Sciamanica e Sentiero Astrale quando sei in difficoltà. Terremoto ed Elementale della Terra sono elencati ma disattivati. Lasciati a te: Grazia dello Spiritista, Folgore del Fuoco su bersagli aggiuntivi e dove posizionarti."
L["rm.mop.shaman.enhancement.Name"] = "Consigliata"
L["rm.mop.shaman.enhancement.Description"] = "Consigliata per Potenziamento dal livello 10, scelta nella specializzazione Potenziamento. L'ordine di Wowhead: Scarica degli Elementi mentre ti avvicini, poi Scarica degli Elementi con Furia Scatenata, Detonazione Elementale e Dardo Fulminante a cinque cumuli di Arma del Maelstrom (o intercalati a tre quando il tuo prossimo colpo è a più di un secondo), Detonazione della Tempesta durante Ascesa, Assalto della Tempesta (Assalto Primordiale prima del livello 26), Sferzata Lavica, Folgore del Fuoco con Scarica delle Fiamme, Scarica degli Elementi, Folgore della Terra. Due o più nemici addosso: Catena di Fulmini invece di Dardo Fulminante, Sferzata Lavica per diffondere Folgore del Fuoco, Esplosione di Fuoco da quattro, Totem del Magma da sei. Promemoria: Scudo di Fulmini, Furia del Vento sulla mano primaria e Lingua di Fuoco sulla mano secondaria, Totem delle Fiamme, Elementale del Fuoco, Spirito Ferino, Ascesa dopo Assalto della Tempesta, Maestria Elementale, Rapidità Ancestrale, Totem della Sferzata della Tempesta e Brama di Sangue in gruppo, Raffica di Vento, Ira Sciamanica e Sentiero Astrale quando sei in difficoltà. Elementale della Terra è elencato ma disattivato."
L["rm.mop.shaman.enhancement.icyveins.Name"] = "Prima Sferzata Lavica (Icy Veins)"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "Disattivata per impostazione predefinita; stesso cambio della rotazione integrata Potenziamento consigliata, quindi per usarla attivala e disattiva l'altra. L'ordine di Icy Veins: Assalto della Tempesta, poi Sferzata Lavica prima di spendere Arma del Maelstrom, Dardo Fulminante a cinque cumuli o da tre quando arriva prima del tuo prossimo colpo, Scarica degli Elementi poi Folgore del Fuoco, Folgore della Terra. Contro quattro o più nemici diffonde Folgore del Fuoco con Sferzata Lavica e usa Esplosione di Fuoco; Catena di Fulmini sostituisce Dardo Fulminante sui gruppi di nemici. Ira Sciamanica viene suggerita appena pronta in combattimento; gli altri promemoria come nella rotazione integrata consigliata."
L["rm.mop.shaman.enhancement.simulator.Name"] = "Intercala ogni cumulo (simulatore)"
L["rm.mop.shaman.enhancement.simulator.Description"] = "Disattivata per impostazione predefinita; stesso cambio della rotazione integrata Potenziamento consigliata, quindi per usarla attivala e disattiva l'altra. La lista del simulatore per i giocatori che sincronizzano i lanci tra i colpi: Dardo Fulminante, Detonazione Elementale o Catena di Fulmini con qualsiasi numero di cumuli di Arma del Maelstrom ogni volta che il lancio finisce prima del tuo prossimo colpo con la mano primaria, Scarica degli Elementi anche ogni volta che manca Folgore del Fuoco, e Folgore della Terra solo sotto due cumuli. Promemoria come nella rotazione integrata consigliata."
L["rm.mop.shaman.restoration.Name"] = "Consigliata"
L["rm.mop.shaman.restoration.Description"] = "Consigliata per Rigenerazione dal livello 10, scelta nella specializzazione Rigenerazione. Cura il tuo bersaglio amico (Rotation Master non può scegliere chi curare): Ondata di Cura Superiore con Rapidità Ancestrale, Eruzione Benefica sotto il 35%, Purificazione Spirituale su Magia o Maledizioni, Scarica degli Elementi poi Pioggia Curativa quando tre alleati vicini sono feriti, Marea Benefica, Catena di Guarigione per i danni al gruppo, Ondata di Cura Superiore sotto il 60%, Ondata di Cura sotto il 90%. Con un bersaglio attaccabile infligge invece danni (Folgore del Fuoco, Getto di Lava, Detonazione Elementale, Dardo Fulminante). Promemoria: Scudo d'Acqua, Terra Benefica, Scudo di Terra sul tuo focus, Totem del Flusso Vitale quando qualcuno è ferito, Totem della Marea di Mana, Totem della Marea Curativa per i danni pesanti al gruppo, Maestria Elementale o Guida Ancestrale, Rapidità Ancestrale su un bersaglio con poca salute, Grazia dello Spiritista in movimento, Brama di Sangue, Raffica di Vento. Ascesa e Totem del Collegamento Spirituale sono elencati ma disattivati: usali quando la tua incursione te li assegna."
L["rm.mop.shaman.restoration.hekili.Name"] = "Scala della salute (Hekili)"
L["rm.mop.shaman.restoration.hekili.Description"] = "Disattivata per impostazione predefinita; stesso cambio della rotazione integrata Rigenerazione consigliata, quindi per usarla attivala e disattiva l'altra. La lista di Hekili mantiene Scudo di Terra e Marea Benefica sul tuo bersaglio e Totem del Flusso Vitale e Pioggia Curativa attivi ogni volta che non lo sono, poi cura in base alla salute media del tuo gruppo entro 40 metri: Catena di Guarigione sotto l'80%, Ondata di Cura su un bersaglio sotto il 70%, Ondata di Cura Superiore sotto il 60%, Eruzione Benefica sotto il 40%, con Totem della Marea Curativa, Guida Ancestrale e Totem della Marea di Mana sulla stessa scala. Un bersaglio attaccabile riceve danni più Folgore della Terra."
L["rm.mop.shaman.unspecialized.Name"] = "Senza specializzazione"
L["rm.mop.shaman.unspecialized.Description"] = "Per i livelli da 1 a 9, e qualsiasi Sciamano che non ha ancora scelto una specializzazione; ogni rotazione integrata di specializzazione subentra appena ne scegli una. Dardo Fulminante per ingaggiare dalla distanza, Eruzione Benefica quando sei basso di salute e da solo, Assalto Primordiale, Folgore della Terra, e Dardo Fulminante mentre sei fuori dalla portata di mischia. Mantiene attivo Scudo di Fulmini."
L["rm.retail.shaman.elemental.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.shaman.elemental.Description"] = "Consigliata per Elementale in Midnight. In combattimento il gioco ora nasconde agli addon Folgore del Fuoco, i tuoi effetti benefici, il Maelstrom, i tempi di recupero e la salute, quindi questa rotazione mostra il suggerimento stesso dell'Assistente di Combattimento di Blizzard (la rotazione a un pulsante), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: Ascesa, Elementale del Fuoco o Elementale della Tempesta e Rapidità della Natura in combattimento, Grazia dello Spiritista in movimento, Scudo di Fulmini e Furia del Cielo tra un ingaggio e l'altro (il suggerimento di Blizzard mantiene gli incantamenti dell'arma e dello scudo), Raffica di Vento su un lancio interrompibile (si illumina solo dove il gioco permette di leggere il lancio), Sentiero Astrale ogni volta che è pronto in combattimento (la salute è nascosta su Retail, quindi decidi tu quando usarlo)."
L["rm.retail.shaman.elemental.icyveins.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.shaman.elemental.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft legge Folgore del Fuoco, Signore degli Elementi e Custode della Tempesta, che Midnight nasconde in combattimento; il Maelstrom è nascosto su Retail, quindi le abilità di consumo vengono usate al loro costo invece che vicino al massimo di Maelstrom. Custode della Tempesta e Getto di Lava prima dell'ingaggio. Contro tre o più nemici ingaggiati: Custode della Tempesta, Rapidità Ancestrale, Folgore del Fuoco, Catena di Fulmini con Custode della Tempesta, Detonazione Elementale, Terremoto, Getto di Lava con Eruzione di Lava, Tempesta, Catena di Fulmini. Altrimenti Custode della Tempesta, Rapidità Ancestrale, Folgore del Fuoco e Fiammata Voltaica nell'ultimo 30% della loro durata fuori da Signore degli Elementi, Getto di Lava per attivarlo, Tempesta e Dardo Fulminante di Custode della Tempesta durante l'effetto, Detonazione Elementale o Folgore della Terra durante l'effetto, Fiammata Voltaica, Tempesta, Folgore del Fuoco o Folgore del Gelo in movimento, Detonazione Elementale o Folgore della Terra ogni volta che te lo puoi permettere, Dardo Fulminante. Promemoria: Ascesa dopo aver usato Custode della Tempesta, gli elementali, Grazia dello Spiritista e quelli comuni."
L["rm.retail.shaman.enhancement.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.shaman.enhancement.Description"] = "Consigliata per Potenziamento in Midnight. Mostra il suggerimento dell'Assistente di Combattimento di Blizzard (spende Arma del Maelstrom, mantiene Folgore del Fuoco e gestisce Totem Crescente e Scissione), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: Ascesa, Venti del Fato e Spirito Ferino in combattimento, Scudo di Fulmini e Furia del Cielo tra un ingaggio e l'altro (il suggerimento di Blizzard mantiene Arma della Furia del Vento), Raffica di Vento, Sentiero Astrale."
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "Araldo della Tempesta, riferimento (SimulationCraft)"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la lista Araldo della Tempesta di SimulationCraft (Icy Veins e Wowhead concordano) legge Folgore del Fuoco, Schianto di Fulmini, Fiamme Sferzanti e i timer dei tempi di recupero, che Midnight nasconde in combattimento. Contro tre o più nemici ingaggiati: Schianto di Fulmini per il suo effetto benefico, Tempesta a 10 cumuli di Arma del Maelstrom, Catena di Fulmini a 9, Schianto di Fulmini, Sferzata Lavica, Scissione. Poi Tempesta Primordiale a 9, Fiammata Voltaica o Folgore del Fuoco quando manca Folgore del Fuoco, Scissione, Schianto di Fulmini per il suo effetto benefico, Sferzata Lavica per Fiamme Sferzanti, Assalto del Vento, Tempesta o Dardo Fulminante a 10 (8 con Fiammata Voltaica o Schianto di Fulmini quasi pronti), Assalto della Tempesta a due cariche, Sferzata Lavica, Assalto della Tempesta, Fiammata Voltaica, Schianto di Fulmini, Dardo Fulminante a 5, Folgore del Fuoco. Promemoria: Venti del Fato, Ascesa fuori da Venti del Fato, Spirito Ferino e quelli comuni."
L["rm.retail.shaman.enhancement.totemic.Name"] = "Totemista, riferimento (SimulationCraft)"
L["rm.retail.shaman.enhancement.totemic.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la lista Totemista di SimulationCraft legge Folgore del Fuoco, Mano Ardente, Fuoco Turbinante, Schianto di Fulmini e Venti del Fato, che Midnight nasconde in combattimento. Contro tre o più nemici ingaggiati: Schianto di Fulmini, Catena di Fulmini a 5 cumuli di Arma del Maelstrom. Poi Fiammata Voltaica o Folgore del Fuoco quando manca Folgore del Fuoco, Totem Crescente, Scissione, Sferzata Lavica con Mano Ardente o Fuoco Turbinante, Schianto di Fulmini per il suo effetto benefico, Tempesta Primordiale a 10, Assalto del Vento, Schianto di Fulmini e Assalto della Tempesta durante Venti del Fato, Dardo Fulminante a 5, Schianto di Fulmini, Sferzata Lavica, Assalto della Tempesta, Fiammata Voltaica, Folgore del Fuoco. Stessi promemoria del riferimento Araldo della Tempesta."
L["rm.retail.shaman.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.shaman.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale dello Sciamano). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata dello Sciamano condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "Rigenerazione in Midnight, a titolo di riferimento: l'Assistente di Combattimento di Blizzard non copre i guaritori, il gioco nasconde la salute di tutti in combattimento e Rotation Master sceglie un incantesimo, non un bersaglio, quindi questa rotazione ordina i tuoi strumenti di cura in base a quando sono pronti su qualunque bersaglio tu abbia e lascia a te la decisione su chi curare. Su un bersaglio amico: Totem del Flusso Vitale, Scarica della Vita, Pioggia Curativa in gruppo, Totem Crescente, Marea Benefica, Catena di Guarigione in gruppo, Ondata di Cura. Su un nemico: Folgore del Fuoco quando manca, Getto di Lava, Dardo Fulminante. Promemoria: Scudo d'Acqua, Scudo di Terra su un bersaglio amico e Furia del Cielo tra un ingaggio e l'altro; Rapidità della Natura in combattimento; Totem della Marea Curativa e Totem del Collegamento Spirituale in combattimento di gruppo; Raffica di Vento; Sentiero Astrale."
L["rm.sod.shaman.elemental.Name"] = "Elementale (SoD)"
L["rm.sod.shaman.elemental.Description"] = "Elementale della Season of Discovery dal livello 10 (la maggior parte dei punti in Elementale); costruita a partire da simulatore Fase 6, Wowhead e Icy Veins. Folgore della Terra interrompe. In movimento: Folgore del Fuoco, Folgore della Terra a otto cariche di Scudo di Fulmini, Getto di Lava o Catena di Fulmini con un proc di Picco Energetico. Contro tre o più nemici: Folgore del Fuoco, Catena di Fulmini, Esplosione di Fuoco, Getto di Lava, Folgore della Terra a otto cariche, Totem del Magma. Poi Getto di Lava con Picco Energetico, Folgore del Fuoco sempre attiva, Getto di Lava finché dura la tua Folgore del Fuoco, Folgore della Terra a otto cariche, Catena di Fulmini contro due nemici, Dardo Fulminante. Promemoria: Lingua di Fuoco per Vampata, Scudo di Fulmini, Scudo di Terra su di te, Spirito dell'Alfa, Spirito Ferino, Ira Sciamanica, Maestria Elementale, totem. Monili, Proiezione Totemica, dissoluzioni ed epurazioni restano a te."
L["rm.sod.shaman.enhancement.Name"] = "Potenziamento (SoD)"
L["rm.sod.shaman.enhancement.Description"] = "Season of Discovery, livelli 1–60 con le rune man mano che le incidi, due armi o arma a due mani, e ogni Sciamano della Season of Discovery a cui non si adatta nessun'altra rotazione integrata; costruita a partire da simulatore Fase 6, Icy Veins e Wowhead. Folgore del Fuoco ingaggia; Folgore della Terra interrompe. Contro tre o più nemici: Totem del Magma, Esplosione di Fuoco da un totem del fuoco, Catena di Fulmini a quattro cumuli di Maelstrom, Folgore del Fuoco. Poi Getto di Lava a cinque cumuli di Maelstrom, Assalto della Tempesta, Sferzata Lavica, Dardo Fulminante a cinque cumuli, Folgore del Fuoco quando farà effetto per tutta la durata, Folgore della Terra, Detonazione Fusa, Dardo Fulminante dalla distanza. Promemoria: Arma della Furia del Vento (prima Arma della Roccia Dura), Arma della Lingua di Fuoco su un'arma nella mano secondaria con Sferzata Lavica (altrimenti Furia del Vento; mai su uno scudo; una riga Icy Veins con Furia del Vento su entrambe è elencata ma disattivata), Scudo d'Acqua o Scudo di Fulmini, Spirito dell'Alfa, Spirito Ferino, Ira Sciamanica sotto il 65% di mana, totem, Guida Ancestrale. Proiezione Totemica, dissoluzioni ed epurazioni restano a te."
L["rm.sod.shaman.restoration.Name"] = "Rigenerazione (SoD)"
L["rm.sod.shaman.restoration.Description"] = "Rigenerazione della Season of Discovery dal livello 10 (la maggior parte dei punti in Rigenerazione); costruita a partire da Icy Veins e Wowhead. Sul tuo bersaglio amico: Marea Benefica e poi Ondata di Cura Inferiore sotto il 40%, Cura dei Veleni o Rimuovi Malattia, Pioggia Curativa quando tre membri del gruppo vicini a te sono sotto l'85%, Catena di Guarigione quando lo sono due (subito con un proc di Picco Energetico), Marea Benefica sotto il 95% per Onde di Marea, Ondata di Cura sotto il 90%. Su un nemico combatte. Promemoria: Scudo d'Acqua (prima Scudo di Fulmini), Scudo di Terra sul tuo bersaglio amico o su di te, Ira Sciamanica, Totem della Marea di Mana, Totem del Flusso di Mana e Totem della Forza della Terra. La scelta di chi curare e i totem del Tremore o purificatori restano a te."
L["rm.sod.shaman.tank.Name"] = "Difensore (SoD, Via della Terra)"
L["rm.sod.shaman.tank.Description"] = "Difensore della Season of Discovery, scelta una volta inciso Via della Terra; costruita a partire da Icy Veins, Wowhead, simulatore e Warcraft Tavern. Folgore del Fuoco ingaggia. Folgore della Terra provoca un bersaglio in mischia che non ti sta attaccando, e interrompe. Contro due o più nemici: Detonazione Fusa, Folgore del Fuoco, Catena di Fulmini a cinque cumuli di Maelstrom o con Picco Energetico, Esplosione di Fuoco a cinque cumuli. Poi Folgore del Fuoco sempre attiva, Getto di Lava con Picco Energetico o finché dura Folgore del Fuoco, Assalto della Tempesta, Folgore della Terra, Dardo Fulminante a cinque cumuli, Detonazione Fusa, Folgore del Gelo. Promemoria: Roccia Dura, Scudo di Fulmini, Spirito dell'Alfa su di te, Spirito Ferino, Ira Sciamanica, Totem delle Fiamme o del Magma, e i totem di gruppo."
L["rm.tbc.shaman.elemental.icyveins.Name"] = "Elementale (Icy Veins & simulatore)"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "Elementale a distanza per l'albero dei talenti Elementale. Dardo del Fulmine è il riempitivo; Catena di Fulmini parte con Signore degli Elementi, con Lucidità finché hai il 40% di mana, oppure liberamente sopra l'80%; Folgore Fiammeggiante solo in movimento; Folgore della Terra per interrompere; Nova di Fuoco, Catena di Fulmini e Totem del Magma contro i gruppi di nemici. Prima di Catena di Fulmini, un bersaglio in mischia viene lasciato all'attacco automatico per risparmiare mana. Promemoria: Scudo d'Acqua o Scudo di Fulmini, un incantamento dell'arma, Totem dell'Ira (o Totem delle Fiamme nei combattimenti lunghi), Ira dell'Aria, Fonte di Mana, Richiamo Totemico dopo il combattimento, Signore degli Elementi e Brama di Sangue/Eroismo."
L["rm.tbc.shaman.elemental.nextaction.Name"] = "Elementale (NextActionTBC)"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "L'Elementale di NextActionTBC, un'alternativa alla rotazione integrata consigliata Elementale di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Mantiene Folgore Fiammeggiante sul bersaglio, Catena di Fulmini solo contro due o più nemici finché il mana è sopra il 30%, altrimenti Dardo del Fulmine. Ti ricorda Scudo di Fulmini, un incantamento dell'arma, Signore degli Elementi e Brama di Sangue/Eroismo; i totem restano manuali."
L["rm.tbc.shaman.elemental.wowhead.Name"] = "Elementale (Wowhead)"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "L'Elementale di Wowhead, un'alternativa alla rotazione integrata consigliata Elementale di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Al livello 70 Catena di Fulmini appena è pronta con Dardi del Fulmine nel mezzo (durante il livellamento solo con Signore degli Elementi o Lucidità), Folgore Fiammeggiante solo in movimento, Folgore della Terra per finire un bersaglio che morirebbe prima che un lancio vada a segno. Stessi promemoria per totem, scudo e tempi di recupero della variante Icy Veins."
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "Potenziamento (Icy Veins)"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "Potenziamento in mischia dal livello 1 al 70, e la scelta predefinita per qualsiasi Sciamano a cui non si adatta nessun'altra rotazione integrata. Ingaggia con Dardo del Fulmine dalla distanza, interrompe con Folgore della Terra, piazza i Totem della Nova di Fuoco e del Magma contro tre o più nemici vicini, poi Assalto della Tempesta, Folgore della Terra finché è attiva la penalità di Assalto della Tempesta, Folgore Fiammeggiante su un bersaglio che sopravvivrà abbastanza, Folgore della Terra appena è pronta e Dardo del Fulmine mentre il bersaglio è fuori portata. Promemoria separati: incantamenti dell'arma, Scudo d'Acqua o Scudo di Fulmini, Forza della Terra, Furia del Vento (in gruppo) o Grazia dell'Aria (da solo), Totem delle Fiamme nei combattimenti lunghi, totem dell'acqua, Ira Sciamanica, Brama di Sangue/Eroismo sui boss, Artiglio di Pietra ed Elementale della Terra quando giochi da solo. L'Elementale del Fuoco è un passaggio facoltativo, disattivato all'inizio. Il posizionamento dei totem, Lupo Spettrale e le cure restano a te."
L["rm.tbc.shaman.enhancement.simulator.Name"] = "Potenziamento (Wowhead & simulatore)"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "Il modello da incursione al livello 70 per l'alternanza dei totem, un'alternativa alla rotazione integrata consigliata Potenziamento di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Assalto della Tempesta, Totem della Nova di Fuoco intercalato, Folgore Fiammeggiante ogni volta che è scaduta e Folgore della Terra come folgore principale, con Dardo del Fulmine solo fuori portata. I promemoria alternano i Totem della Furia del Vento e della Grazia dell'Aria, mantengono il Totem delle Fiamme, usano Ira Sciamanica quando il mana scarseggia e condividono con la variante Icy Veins gli incantamenti, lo scudo e la gestione dei totem."
L["rm.tbc.shaman.restoration.Name"] = "Rigenerazione"
L["rm.tbc.shaman.restoration.Description"] = "Cure per l'albero dei talenti Rigenerazione, sul tuo bersaglio amico (o su di te se non hai un bersaglio): Rapidità della Natura e Onda di Guarigione o Onda di Guarigione Inferiore nelle emergenze, Cura Veleno e Cura Malattia, Scudo di Terra sul tuo focus, Catena di Guarigione quando tre alleati vicini sono feriti, altrimenti Onda di Guarigione. Con un bersaglio ostile passa a Folgore Fiammeggiante e Dardo del Fulmine per giocare da solo. Promemoria: Scudo d'Acqua, Scudo di Terra sul tuo focus (imposta il difensore come focus), Marea di Mana, Fonte di Mana e Forza della Terra in gruppo, Brama di Sangue/Eroismo. La scelta di chi curare e con quale grado resta a te."
